/*
 * mission_control.js — "Lift Off" program tracker, mounted as a COLLAPSIBLE
 * block BELOW the RACI functions in the Team & RACI tab (#tab-raci). STATIC asset (NOT
 * regenerated by excel_to_dashboard.py; NOT a daily-cron artifact).
 *
 * Structure comes from the committed kb/liftoff_plan.json (phases → task +
 * decision nodes). Live status + decision choices are an overlay on Supabase
 * `liftoff_state` (anon read; reviewer-gated write via is_allowed_reviewer()) —
 * the factsheet_overrides / card_updates pattern: committed file = the default,
 * Supabase = the reviewer overlay, render = file ⊕ overlay.
 *
 * The "branch at key steps" model: a `decision` node forks the work. Choosing an
 * option ACTIVATES its branch tasks and ARCHIVES the others; an undecided
 * decision leaves its branch tasks `pending`. The choice is the human-owned
 * decision log (HUMANS principle 2 — AI proposes, a named human disposes).
 *
 * Auth: reuses the SHARED magic-link session (sessionStorage `cpl_sb`) minted by
 * the RACI tab's Curator sign-in — no second sign-in UI. The ~40 lines of
 * session/refresh/write helpers below are deliberately mirrored from raci.js;
 * they're a known duplication that the planned `cobi-auth.js` consolidation
 * (a NOW task in this very tracker) will absorb. Mirrors the
 * refresh-token-before-write fix (docs/kb-notes/methodology-refresh-token-before-write.md).
 *
 * Tests: tests/mission_control.test.js.
 */
(function () {
  "use strict";

  var SUPABASE_URL = "https://hvuwhnbuahrtptokpqfh.supabase.co";
  var SUPABASE_ANON = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Imh2dXdobmJ1YWhydHB0b2twcWZoIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzU1NzI0ODEsImV4cCI6MjA5MTE0ODQ4MX0.p0q-93iTM0GkF2z8_q7Vvl1tsX9SFGMM-W7Wdx7WfmM";
  var PLAN_URL = "kb/liftoff_plan.json";

  var state = { sess: null };
  var cache = { plan: null, overlay: {}, loadingPlan: false };

  // ─── Status vocabulary (label + css class) ─────────────────────────────────
  var STATUS = {
    not_started:      { label: "Not started",  cls: "mc-st-not" },
    in_progress:      { label: "In progress",  cls: "mc-st-prog" },
    blocked:          { label: "Blocked",      cls: "mc-st-blk" },
    pending_decision: { label: "Pending decision", cls: "mc-st-pend" },
    done:             { label: "Done",         cls: "mc-st-done" },
    skipped:          { label: "Not taken",    cls: "mc-st-skip" }
  };
  var EDITABLE_STATUS = ["not_started", "in_progress", "blocked", "done"];
  function statusMeta(s) { return STATUS[s] || STATUS.not_started; }

  // ─── Auth (shared cpl_sb session) — mirrors raci.js ────────────────────────
  function isValidJwt(t) { return typeof t === "string" && /^[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$/.test(t); }
  function getSession() {
    try {
      var s = JSON.parse(sessionStorage.getItem("cpl_sb") || "null");
      if (s && isValidJwt(s.access_token) && (s.refresh_token || !s.exp || s.exp > Date.now())) return s;
    } catch (e) {}
    return null;
  }
  // Shared "team phrase" edit gate — mirrors raci.js so unlocking the Team & RACI
  // tab also unlocks Mission Control (it lives in the same tab). The phrase is the
  // x-team-pass header the liftoff_state RLS validates via team_pass_ok().
  function teamSession() {
    try { var p = localStorage.getItem("cpl_team_pass"); if (p) return { teamPass: p, email: "(team)" }; } catch (e) {}
    return null;
  }
  function anySession() { return getSession() || teamSession(); }
  function refreshToken(rt) {
    return fetch(SUPABASE_URL + "/auth/v1/token?grant_type=refresh_token", {
      method: "POST", headers: { apikey: SUPABASE_ANON, "Content-Type": "application/json" },
      body: JSON.stringify({ refresh_token: rt })
    }).then(function (r) { return r.ok ? r.json() : Promise.reject(new Error("refresh " + r.status)); });
  }
  function ensureFresh() {
    // Re-read: refresh tokens rotate, so a cached session can hold a CONSUMED
    // one after a sibling module (or the cpl_session.js keeper) renewed. See
    // credential_reference.js — same line, same reason.
    var s = getSession() || state.sess;
    if (!s) return Promise.resolve(null);
    state.sess = s;
    if (s.exp && s.exp <= Date.now() + 60000 && s.refresh_token) {
      return refreshToken(s.refresh_token).then(function (tok) {
        if (!isValidJwt(tok.access_token)) throw new Error("bad refresh");
        s = { access_token: tok.access_token, refresh_token: tok.refresh_token || s.refresh_token,
          email: s.email, exp: Date.now() + (parseInt(tok.expires_in || "3600", 10) * 1000) };
        state.sess = s;
        try { sessionStorage.setItem("cpl_sb", JSON.stringify(s)); } catch (e) {}
        return s;
      }).catch(function () {
        state.sess = null; try { sessionStorage.removeItem("cpl_sb"); } catch (e) {}
        return null;
      });
    }
    return Promise.resolve(s);
  }
  function sbGet(path) {
    return fetch(SUPABASE_URL + "/rest/v1/" + path, { headers: { apikey: SUPABASE_ANON } })
      .then(function (r) { return r.ok ? r.json() : []; }).catch(function () { return []; });
  }
  function headersFor(s, prefer) {
    // A team-phrase (or anon) session has no user token — fall back to the anon
    // key as the bearer, NOT an empty "Bearer " (PostgREST 401s a malformed JWT
    // at the auth layer before RLS runs — the same bug fixed in raci.js).
    var token = (s && s.access_token) || SUPABASE_ANON;
    var headers = { apikey: SUPABASE_ANON, "Content-Type": "application/json", Authorization: "Bearer " + token };
    if (s && s.teamPass) headers["x-team-pass"] = s.teamPass;   // shared-phrase gate → RLS team_pass_ok()
    if (prefer) headers.Prefer = prefer;
    return headers;
  }
  function sbWrite(method, path, body, prefer) {
    return ensureFresh().then(function (s) {
      return fetch(SUPABASE_URL + "/rest/v1/" + path, { method: method, headers: headersFor(s, prefer), body: JSON.stringify(body) });
    });
  }

  // ─── Data ──────────────────────────────────────────────────────────────────
  function ensurePlan() {
    if (cache.plan) return Promise.resolve(cache.plan);
    return fetch(PLAN_URL).then(function (r) { return r.ok ? r.json() : null; })
      .then(function (p) { cache.plan = p; return p; })
      .catch(function () { return null; });
  }
  function loadOverlay() {
    return sbGet("liftoff_state?select=id,status,chosen,updated_by,updated_at");
  }
  function overlayMapFromRows(rows) {
    var m = {};
    (rows || []).forEach(function (r) { if (r && r.id) m[r.id] = r; });
    return m;
  }

  // ─── Effective-state resolution (the branch model) ─────────────────────────
  function findNode(plan, id) {
    if (!plan) return null;
    for (var i = 0; i < plan.phases.length; i++) {
      var ns = plan.phases[i].nodes;
      for (var j = 0; j < ns.length; j++) if (ns[j].id === id) return ns[j];
    }
    return null;
  }
  function decisionChosen(decId, plan, overlay) {
    if (overlay[decId] && overlay[decId].chosen) return overlay[decId].chosen;
    var n = findNode(plan, decId);
    return (n && n.chosen) || null;
  }
  function chosenOption(decId, plan, overlay) {
    var n = findNode(plan, decId);
    if (!n || !n.options) return null;
    var ch = decisionChosen(decId, plan, overlay);
    if (!ch) return null;
    for (var i = 0; i < n.options.length; i++) if (n.options[i].id === ch) return n.options[i];
    return null;
  }
  // Returns { state: 'active'|'pending'|'archived', status: <effective status> }.
  function taskState(task, plan, overlay) {
    var eff = (overlay[task.id] && overlay[task.id].status) || task.status || "not_started";
    if (task.needs) {
      var opt = chosenOption(task.needs, plan, overlay);
      if (!opt) return { state: "pending", status: "pending_decision" };
      if ((opt.activates || []).indexOf(task.id) !== -1) {
        if (eff === "pending_decision") eff = "not_started";
        return { state: "active", status: eff };
      }
      return { state: "archived", status: "skipped" };
    }
    return { state: "active", status: eff };
  }
  function phaseStats(phase, plan, overlay) {
    var active = 0, done = 0;
    phase.nodes.forEach(function (n) {
      if (n.type !== "task") return;
      var ts = taskState(n, plan, overlay);
      if (ts.state !== "active") return;
      active++;
      if (ts.status === "done") done++;
    });
    return { active: active, done: done, pct: active ? Math.round((done / active) * 100) : 0 };
  }

  // ─── DOM helpers (textContent only — overlay carries reviewer-entered text) ──
  function mk(doc, tag, props, kids) {
    var e = doc.createElement(tag);
    props = props || {};
    Object.keys(props).forEach(function (k) {
      if (k === "class") e.className = props[k];
      else if (k === "text") e.textContent = props[k];
      else if (k === "title") e.setAttribute("title", props[k]);
      else if (k === "html") e.innerHTML = props[k]; // only for trusted static markup
      else e.setAttribute(k, props[k]);
    });
    (kids || []).forEach(function (c) { if (c) e.appendChild(c); });
    return e;
  }

  function statusBadge(doc, status) {
    var m = statusMeta(status);
    return mk(doc, "span", { class: "mc-badge " + m.cls, text: m.label });
  }
  function chip(doc, cls, text) { return mk(doc, "span", { class: "mc-chip " + cls, text: text }); }

  function taskRow(doc, task, plan, overlay, ctx) {
    var ts = taskState(task, plan, overlay);
    var row = mk(doc, "div", { class: "mc-task mc-state-" + ts.state, "data-id": task.id });

    // Status: a <select> for a signed-in reviewer on an ACTIVE task; else a badge.
    if (ctx.signedIn && ts.state === "active" && typeof ctx.onStatus === "function") {
      var sel = mk(doc, "select", { class: "mc-status-sel", "aria-label": "Status for " + task.title });
      EDITABLE_STATUS.forEach(function (s) {
        var o = mk(doc, "option", { value: s, text: statusMeta(s).label });
        if (s === ts.status) o.setAttribute("selected", "selected");
        sel.appendChild(o);
      });
      sel.value = ts.status;
      sel.addEventListener("change", function () { ctx.onStatus(task.id, sel.value); });
      row.appendChild(sel);
    } else {
      row.appendChild(statusBadge(doc, ts.status));
    }

    if (task.lane) row.appendChild(chip(doc, "mc-lane", task.lane));
    if (task.owner) row.appendChild(chip(doc, "mc-owner", task.owner));

    var body = mk(doc, "div", { class: "mc-task-body" });
    body.appendChild(mk(doc, "div", { class: "mc-task-title", text: task.title }));
    if (ts.state === "pending") {
      var dn = findNode(plan, task.needs);
      body.appendChild(mk(doc, "div", { class: "mc-task-sub mc-pending-note",
        text: "⌛ waiting on decision: " + (dn ? dn.title : task.needs) }));
    } else if (ts.state === "archived") {
      body.appendChild(mk(doc, "div", { class: "mc-task-sub mc-archived-note", text: "branch not taken" }));
    } else if (task.note) {
      body.appendChild(mk(doc, "div", { class: "mc-task-sub", text: task.note }));
    }
    row.appendChild(body);
    return row;
  }

  function decisionCard(doc, dec, plan, overlay, ctx) {
    var chosenId = decisionChosen(dec.id, plan, overlay);
    var card = mk(doc, "div", { class: "mc-decision" + (chosenId ? " mc-decided" : ""), "data-id": dec.id });
    var head = mk(doc, "div", { class: "mc-decision-head" });
    head.appendChild(mk(doc, "span", { class: "mc-decision-icon", text: "⌥" }));
    head.appendChild(mk(doc, "span", { class: "mc-decision-title", text: "Decision: " + dec.title }));
    if (dec.owner) head.appendChild(chip(doc, "mc-owner", dec.owner));
    card.appendChild(head);
    if (dec.question) card.appendChild(mk(doc, "div", { class: "mc-decision-q", text: dec.question }));

    (dec.options || []).forEach(function (opt) {
      var isChosen = chosenId === opt.id;
      var oEl = mk(doc, "div", { class: "mc-option" + (isChosen ? " mc-option-chosen" : "") });
      var lab = mk(doc, "div", { class: "mc-option-label" });
      if (opt.recommended) lab.appendChild(mk(doc, "span", { class: "mc-rec", title: "Recommended", text: "★ " }));
      lab.appendChild(doc.createTextNode(opt.label));
      oEl.appendChild(lab);
      if (opt.summary) oEl.appendChild(mk(doc, "div", { class: "mc-option-sum", text: opt.summary }));
      if (ctx.signedIn && typeof ctx.onChoose === "function") {
        var btn = mk(doc, "button", { class: "mc-choose" + (isChosen ? " mc-choose-on" : ""), type: "button",
          text: isChosen ? "✓ Chosen" : "Choose" });
        if (!isChosen) btn.addEventListener("click", function () { ctx.onChoose(dec.id, opt.id); });
        oEl.appendChild(btn);
      } else if (isChosen) {
        oEl.appendChild(mk(doc, "span", { class: "mc-chosen-tag", text: "✓ chosen" }));
      }
      card.appendChild(oEl);
    });
    return card;
  }

  function progressBar(doc, pct, label) {
    var wrap = mk(doc, "div", { class: "mc-prog", title: label });
    wrap.appendChild(mk(doc, "div", { class: "mc-prog-fill", style: "width:" + pct + "%;" }));
    return wrap;
  }

  // buildSection(doc, plan, overlay, ctx) → the collapsible Mission Control block
  // (an outer <details>). ctx = { signedIn, email, onStatus(id,status), onChoose(decId,optId) }.
  function buildSection(doc, plan, overlay, ctx) {
    ctx = ctx || {};
    overlay = overlay || {};
    var sec = mk(doc, "details", { class: "mc-section mc-collapsible" });
    sec.setAttribute("open", "open");
    var sum = mk(doc, "summary", { class: "mc-sumhead" });
    sum.appendChild(mk(doc, "span", { class: "mc-h3", text: "🚀 " + ((plan && plan._mission) || "Lift Off") + " — " + ((plan && plan._surface) || "Mission Control") }));
    sec.appendChild(sum);
    if (!plan || !plan.phases) {
      sec.appendChild(mk(doc, "p", { class: "mc-empty", text: "Mission Control plan unavailable." }));
      return sec;
    }

    var totA = 0, totD = 0;
    plan.phases.forEach(function (ph) { var s = phaseStats(ph, plan, overlay); totA += s.active; totD += s.done; });
    sum.appendChild(mk(doc, "span", { class: "mc-count", text: totD + " / " + totA + " active tasks done" }));

    var body = mk(doc, "div", { class: "mc-body" });
    body.appendChild(progressBar(doc, totA ? Math.round((totD / totA) * 100) : 0, "Overall progress"));
    if (plan._status) body.appendChild(mk(doc, "div", { class: "mc-status-line", text: plan._status }));
    body.appendChild(mk(doc, "div", { class: "mc-auth-hint",
      text: ctx.signedIn ? ("✎ Editing as " + (ctx.email || "reviewer") + " — set task status & decisions below.")
                         : "Sign in via the Curator sign-in (in the Team Directory above) to update status & make decisions." }));

    plan.phases.forEach(function (ph, i) {
      var st = phaseStats(ph, plan, overlay);
      var det = mk(doc, "details", { class: "mc-phase" });
      if (i === 0) det.setAttribute("open", "open");
      var psum = mk(doc, "summary", { class: "mc-phase-sum" });
      psum.appendChild(mk(doc, "span", { class: "mc-phase-label", text: ph.label }));
      psum.appendChild(mk(doc, "span", { class: "mc-phase-count", text: st.done + "/" + st.active }));
      psum.appendChild(progressBar(doc, st.pct, ph.label));
      det.appendChild(psum);
      if (ph.gate) det.appendChild(mk(doc, "div", { class: "mc-gate", text: "⛳ Gate to next: " + ph.gate }));
      var list = mk(doc, "div", { class: "mc-list" });
      ph.nodes.forEach(function (n) {
        if (n.type === "decision") list.appendChild(decisionCard(doc, n, plan, overlay, ctx));
        else list.appendChild(taskRow(doc, n, plan, overlay, ctx));
      });
      det.appendChild(list);
      body.appendChild(det);
    });
    sec.appendChild(body);
    return sec;
  }

  // ─── Persistence (optimistic + rollback) ───────────────────────────────────
  function upsert(row) {
    var s = anySession();
    row.updated_by = (s && s.email) || null;
    row.updated_at = new Date().toISOString();
    return sbWrite("POST", "liftoff_state", row, "resolution=merge-duplicates,return=minimal")
      .then(function (r) { if (!r || !r.ok) throw new Error("write " + (r && r.status)); });
  }
  function setStatus(id, status) {
    var prev = cache.overlay[id] ? cache.overlay[id].status : undefined;
    cache.overlay[id] = Object.assign({}, cache.overlay[id], { id: id, status: status });
    render();
    upsert({ id: id, status: status }).catch(function () {
      if (prev === undefined) { if (cache.overlay[id]) delete cache.overlay[id].status; }
      else cache.overlay[id].status = prev;
      render();
      try { window.alert("Couldn't save status — make sure you're signed in (Curator sign-in below)."); } catch (e) {}
    });
  }
  function setChoice(decId, optId) {
    var prev = cache.overlay[decId] ? cache.overlay[decId].chosen : undefined;
    cache.overlay[decId] = Object.assign({}, cache.overlay[decId], { id: decId, chosen: optId });
    render();
    upsert({ id: decId, chosen: optId }).catch(function () {
      if (prev === undefined) { if (cache.overlay[decId]) delete cache.overlay[decId].chosen; }
      else cache.overlay[decId].chosen = prev;
      render();
      try { window.alert("Couldn't save the decision — make sure you're signed in (Curator sign-in below)."); } catch (e) {}
    });
  }

  // ─── Mount / render ────────────────────────────────────────────────────────
  function ctxFromState() {
    return { signedIn: !!state.sess, email: state.sess && state.sess.email, onStatus: setStatus, onChoose: setChoice };
  }
  function render() {
    var host = document.getElementById("mission-control-root");
    if (!host || !cache.plan) return;
    var sec = buildSection(document, cache.plan, cache.overlay, ctxFromState());
    host.innerHTML = "";
    host.appendChild(sec);
  }
  function ensureHost() {
    var anchor = document.getElementById("raci-root");
    if (!anchor || !anchor.parentNode) return null;
    var host = document.getElementById("mission-control-root");
    if (!host) {
      host = document.createElement("div");
      host.id = "mission-control-root";
      // Mount BELOW the RACI functions (the matrix + directory live in #raci-root).
      anchor.parentNode.insertBefore(host, anchor.nextSibling);
    }
    return host;
  }
  function run() {
    ensureCss();
    var host = ensureHost();
    if (!host) return;
    state.sess = anySession();
    if (!host.getAttribute("data-loading")) {
      host.setAttribute("data-loading", "1");
      host.appendChild(mk(document, "p", { class: "mc-empty", text: "Loading Mission Control…" }));
    }
    ensurePlan().then(function (plan) {
      if (!plan) { host.innerHTML = ""; return; }
      loadOverlay().then(function (rows) {
        cache.overlay = overlayMapFromRows(rows);
        state.sess = anySession();
        render();
      });
    });
  }

  function ensureCss() {
    if (document.getElementById("mc-css")) return;
    var css =
      ".mc-section{margin:0 0 1.4rem;border:1px solid var(--border,#d4dde7);border-radius:10px;background:var(--surface,#fff);padding:.9rem 1rem;}" +
      ".mc-section>summary.mc-sumhead{list-style:none;cursor:pointer;display:flex;align-items:baseline;justify-content:space-between;gap:.6rem;flex-wrap:wrap;}" +
      ".mc-section>summary.mc-sumhead::-webkit-details-marker{display:none;}" +
      ".mc-collapsible>summary .mc-h3::before{content:'\\25BE  ';font-size:.85em;color:var(--text-muted,#778);}" +
      ".mc-collapsible:not([open])>summary .mc-h3::before{content:'\\25B8  ';}" +
      ".mc-body{margin-top:.7rem;}" +
      ".mc-phase>summary .mc-phase-label::before{content:'\\25BE  ';font-size:.8em;color:var(--text-muted,#778);}" +
      ".mc-phase:not([open])>summary .mc-phase-label::before{content:'\\25B8  ';}" +
      ".mc-h3{margin:0;font-size:1.05rem;color:var(--navy-secondary,#1c3d5a);}" +
      ".mc-count{font-size:.78rem;color:var(--text-muted,#667);font-weight:600;}" +
      ".mc-status-line{margin:.45rem 0 .2rem;font-size:.82rem;color:var(--text-muted,#556);font-style:italic;}" +
      ".mc-auth-hint{font-size:.75rem;color:var(--text-muted,#667);margin-top:.25rem;}" +
      ".mc-prog{height:7px;border-radius:5px;background:var(--surface-2,#eef3f9);overflow:hidden;margin:.4rem 0;min-width:90px;flex:1 1 90px;}" +
      ".mc-prog-fill{height:100%;background:var(--ok,#2e7d32);border-radius:5px;transition:width .3s;}" +
      ".mc-phase{border-top:1px solid var(--border,#e3e9f0);padding:.35rem 0;}" +
      ".mc-phase>summary{list-style:none;cursor:pointer;display:flex;align-items:center;gap:.6rem;padding:.4rem .1rem;}" +
      ".mc-phase>summary::-webkit-details-marker{display:none;}" +
      ".mc-phase-label{font-weight:700;color:var(--navy-secondary,#1c3d5a);font-size:.9rem;flex:0 0 auto;}" +
      ".mc-phase-count{font-size:.74rem;color:var(--text-muted,#667);font-weight:600;}" +
      ".mc-gate{font-size:.74rem;color:var(--text-muted,#667);background:var(--surface-2,#f4f7fb);border-radius:6px;padding:.3rem .5rem;margin:.2rem 0 .5rem;}" +
      ".mc-list{display:flex;flex-direction:column;gap:.35rem;}" +
      ".mc-task{display:flex;align-items:flex-start;gap:.5rem;padding:.35rem .5rem;border:1px solid var(--border,#e3e9f0);border-radius:7px;background:var(--surface,#fff);flex-wrap:wrap;}" +
      ".mc-task-body{flex:1 1 240px;min-width:160px;}" +
      ".mc-task-title{font-size:.84rem;color:var(--text,#243b53);line-height:1.3;}" +
      ".mc-task-sub{font-size:.72rem;color:var(--text-muted,#778);margin-top:.15rem;}" +
      ".mc-state-pending{opacity:.72;border-style:dashed;}" +
      ".mc-state-archived{opacity:.5;}" +
      ".mc-state-archived .mc-task-title{text-decoration:line-through;}" +
      ".mc-pending-note{color:var(--gold-accent,#B8860B);}" +
      ".mc-badge{font-size:.66rem;font-weight:700;border-radius:4px;padding:.12rem .4rem;white-space:nowrap;}" +
      ".mc-st-not{background:var(--surface-2,#eef3f9);color:var(--text-muted,#667);}" +
      ".mc-st-prog{background:#e3eefb;color:#1c5d99;}" +
      ".mc-st-blk{background:#fbe4e2;color:#b3261e;}" +
      ".mc-st-pend{background:var(--gold-soft,#fbf3d9);color:var(--gold-accent,#8a6608);}" +
      ".mc-st-done{background:#e2f3e6;color:#2e7d32;}" +
      ".mc-st-skip{background:#f0f0f2;color:#999;}" +
      ".mc-status-sel{font-size:.7rem;border:1px solid var(--border,#d4dde7);border-radius:5px;padding:.1rem .2rem;background:var(--surface,#fff);color:var(--text,#243b53);}" +
      ".mc-chip{font-size:.66rem;border-radius:4px;padding:.12rem .4rem;white-space:nowrap;}" +
      ".mc-lane{background:var(--surface-2,#eef3f9);color:#4a5b70;}" +
      ".mc-owner{background:var(--navy-secondary,#1c3d5a);color:#fff;}" +
      ".mc-decision{border:1px solid var(--gold-accent,#B8860B);border-radius:8px;background:var(--gold-soft,#fbf3d9);padding:.5rem .6rem;}" +
      ".mc-decided{border-color:var(--ok,#2e7d32);background:#eef7f0;}" +
      ".mc-decision-head{display:flex;align-items:center;gap:.4rem;flex-wrap:wrap;}" +
      ".mc-decision-icon{font-weight:800;color:var(--gold-accent,#8a6608);}" +
      ".mc-decision-title{font-weight:700;font-size:.86rem;color:var(--navy-secondary,#1c3d5a);}" +
      ".mc-decision-q{font-size:.76rem;color:var(--text-muted,#556);margin:.25rem 0 .4rem;}" +
      ".mc-option{display:flex;flex-direction:column;gap:.15rem;padding:.35rem .45rem;margin:.3rem 0;border:1px solid var(--border,#e3e9f0);border-radius:6px;background:var(--surface,#fff);}" +
      ".mc-option-chosen{border-color:var(--ok,#2e7d32);box-shadow:0 0 0 1px var(--ok,#2e7d32) inset;}" +
      ".mc-option-label{font-size:.8rem;font-weight:600;color:var(--text,#243b53);}" +
      ".mc-option-sum{font-size:.72rem;color:var(--text-muted,#778);}" +
      ".mc-rec{color:var(--gold-accent,#B8860B);}" +
      ".mc-choose{align-self:flex-start;margin-top:.2rem;font-size:.7rem;font-weight:600;color:var(--accent-link,#1c5d99);background:var(--surface-2,#eef3f9);border:1px solid var(--border,#d4dde7);border-radius:5px;padding:.12rem .5rem;cursor:pointer;}" +
      ".mc-choose:hover{background:var(--gold-soft,#fbf3d9);border-color:var(--gold-accent,#B8860B);}" +
      ".mc-choose-on{color:#2e7d32;background:#e2f3e6;border-color:#2e7d32;cursor:default;}" +
      ".mc-chosen-tag{align-self:flex-start;font-size:.7rem;font-weight:700;color:#2e7d32;}" +
      ".mc-empty{color:var(--text-muted,#888);font-size:.85rem;padding:.5rem;}";
    var st = document.createElement("style");
    st.id = "mc-css";
    st.textContent = css;
    document.head.appendChild(st);
  }

  // ─── Wiring: mount on RACI tab activation (+ on load if already there) ──────
  window.addEventListener("cpl-tab-activated", function (e) {
    if (e && e.detail && e.detail.tab === "raci") run();
  });
  function bootIfOnRaci() {
    if ((location.hash || "").replace(/^#/, "") === "raci") run();
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", bootIfOnRaci);
  } else {
    bootIfOnRaci();
  }

  window.CPL_MISSION_CONTROL = {
    run: run, render: render, buildSection: buildSection,
    taskState: taskState, phaseStats: phaseStats, statusMeta: statusMeta,
    overlayMap: overlayMapFromRows, _findNode: findNode, _decisionChosen: decisionChosen,
    _setCache: function (p, o) { cache.plan = p; cache.overlay = o || {}; },
    _headersFor: headersFor, _teamSession: teamSession, _anySession: anySession
  };
})();
